mapper.select:
SELECT q.id, q.bank_id, q.question_no, q.position_id, q.qtype, q.difficulty, q.knowledge_point,
       q.stem, q.options_json, q.attachment_url, q.answer, q.analysis, q.score, q.is_subjective, q.status
FROM question q
WHERE q.deleted = 0 AND q.status = 1
  AND q.bank_id = #{bankId}

  AND q.knowledge_point = #{point}


  AND q.qtype = #{qtype}


  AND q.id NOT IN
  #{eid}

ORDER BY RAND()
LIMIT #{limit}
